scripts.event-desk-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { type RosterRecord, ledgerStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'event-desk-store',
  description:
    "Read and update the event desk: event.json (the event's details and run of show), venues.json, vendors.json and guests.json (rosters), and budget.json (payments in integer cents). action:'status' for the whole picture; 'compare' to compare the venues for a headcount; 'add_venue', 'book_venue', 'add_vendor', 'pay', 'add_guest', 'rsvp', 'set_event' and 'program' to change it; 'guests' for the whole guest list. An add with an existing name updates that record, never duplicates it. Amounts are in dollars.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'compare', 'add_venue', 'book_venue', 'add_vendor', 'pay', 'add_guest', 'rsvp', 'set_event', 'program', or 'guests'.",
      required: true,
    },
    id: { type: 'string', description: "A record id: a venue 've-2', a vendor 'vn-3' or a guest 'gu-12'." },
    name: {
      type: 'string',
      description: "The venue's, vendor's or guest's name. Also finds the record when no id is given.",
    },
    occasion: { type: 'string', description: "The event's name, e.g. 'Fernwood Client Summit'." },
    date: { type: 'string', description: 'The event date, YYYY-MM-DD.' },
    time: {
      type: 'string',
      description:
        "For set_event, the event's hours as they should be printed ('3:00 to 8:30 pm'). For program, the item's start time ('4:30 pm' or '16:30').",
    },
    host: { type: 'string', description: 'Who hosts the event.' },
    rsvp: { type: 'string', description: 'How and by when guests reply, exactly as it should be printed.' },
    headcount: { type: 'number', description: 'How many guests the event plans for.' },
    budget: { type: 'number', description: 'The whole budget in dollars (replaces it).' },
    budgetChange: { type: 'number', description: 'Dollars to add to the budget (negative to cut it).' },
    capacity: { type: 'number', description: 'How many guests the venue holds.' },
    fee: { type: 'number', description: "The venue's hire fee in dollars." },
    cateringPerHead: {
      type: 'number',
      description: 'In-house catering per guest in dollars; leave it out when you bring your own caterer.',
    },
    av: { type: 'string', description: "Whether sound and screens come with the venue: 'included' or 'extra'." },
    location: { type: 'string', description: 'Where the venue is.' },
    category: {
      type: 'string',
      description: 'venue, catering, av, entertainment, photography, rentals, decor, transport, or other.',
    },
    contract: { type: 'number', description: "The vendor's agreed or quoted total in dollars (replaces it)." },
    contractChange: {
      type: 'number',
      description: "Dollars to add to the vendor's total (negative when it drops).",
    },
    deposit: { type: 'number', description: 'The deposit in dollars.' },
    depositDueAt: { type: 'string', description: 'When the deposit is due, YYYY-MM-DD.' },
    contact: { type: 'string', description: 'Who to call at the vendor, with a number.' },
    arrival: { type: 'string', description: "When the vendor arrives on the day ('2 pm' or '14:00')." },
    amount: { type: 'number', description: 'A payment in dollars.' },
    kind: { type: 'string', description: 'For pay: deposit, balance, or other.' },
    company: { type: 'string', description: "The guest's company." },
    response: { type: 'string', description: 'invited, yes, or no.' },
    dietary: {
      type: 'string',
      description: "What the guest can't eat, as they said it ('vegetarian', 'nut allergy'), or 'none'.",
    },
    partySize: {
      type: 'number',
      description: 'How many people the invitation covers, the guest included (replaces it).',
    },
    joining: { type: 'number', description: 'How many extra people come with this guest (added to their party).' },
    item: { type: 'string', description: "A run-of-show item, e.g. 'Welcome from Fernwood'." },
    owner: { type: 'string', description: "Who's on point for the item." },
    remove: { type: 'boolean', description: 'For program: take the item off the run of show.' },
    status: {
      type: 'string',
      description: 'A venue: shortlisted, visited, held, or declined. A vendor: quoted, booked, or dropped.',
    },
    note: { type: 'string', description: 'Anything to keep with it, with reference numbers exactly as written.' },
    guests: {
      type: 'number',
      description: 'For compare: the headcount to compare for (default: the planned headcount).',
    },
  },
  outputs: {
    attending: { type: 'number', description: 'People coming: yes answers with the guests they bring.' },
    noDietaryAnswer: { type: 'array', itemType: 'string', description: 'Every attending guest with no dietary answer yet, by name.' },
    budgetLeft: { type: 'number', description: 'Budget not yet committed to booked vendors, in dollars.' },
    summary: {
      type: 'string',
      description: 'What changed first, then the whole picture (or the venue comparison, or the guest list).',
    },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── event-desk-rules-start ──
// Pure derivations: money in integer cents, local calendar days, clock times,
// dietary answers, the venue comparison and the desk picture the crew reads.
// Kept self-contained between these sentinels so tests (and the page's demo)
// execute the shipped bytes.
var DAY_MS = 86400000;
var VENUE_STAGES = ['shortlisted', 'visited', 'held', 'booked', 'declined'];
var VENDOR_STAGES = ['quoted', 'booked', 'paid', 'dropped'];
var GUEST_STAGES = ['invited', 'yes', 'no'];
var VENDOR_KINDS = ['venue', 'catering', 'av', 'entertainment', 'photography', 'rentals', 'decor', 'transport', 'other'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function isDay(text) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(text || ''));
}
function normalizeDate(text, nowMs) {
  var raw = String(text || '').trim();
  if (isDay(raw)) return raw;
  // Only something that reads as a date: a month name with a day, or numbers like 12/10.
  if (!/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+\d|\d\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)|\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}/i.test(raw)) return null;
  if (/\d{4}/.test(raw)) {
    var full = Date.parse(raw);
    return isFinite(full) ? localDay(full) : null;
  }
  // 'December 10' names the next December 10, not one in 2001.
  var now = new Date(nowMs || Date.now());
  var parsed = Date.parse(raw + ' ' + now.getFullYear());
  if (!isFinite(parsed)) return null;
  if (parsed < now.getTime() - 31 * DAY_MS) parsed = Date.parse(raw + ' ' + (now.getFullYear() + 1));
  return localDay(parsed);
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function when(days) {
  if (days < 0) return -days + (days === -1 ? ' day late' : ' days late');
  if (days === 0) return 'due today';
  return 'in ' + days + (days === 1 ? ' day' : ' days');
}
function key(text) {
  return String(text || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9&]+/g, ' ')
    .trim();
}
// 'exact', 'partial' (the name starts with the words given, or contains them whole), or ''.
function nameMatch(name, wanted) {
  var have = key(name);
  var want = key(wanted);
  if (!have || !want) return '';
  if (have === want) return 'exact';
  return (' ' + have).indexOf(' ' + want) >= 0 || (' ' + want + ' ').indexOf(' ' + have + ' ') >= 0 ? 'partial' : '';
}
function toCents(amount) {
  var n = typeof amount === 'string' ? Number(String(amount).replace(/[$,\s]/g, '')) : amount;
  return typeof n === 'number' && isFinite(n) ? Math.round(n * 100) : null;
}
function money(cents) {
  var c = Math.round(Number(cents) || 0);
  var sign = c < 0 ? '-' : '';
  c = Math.abs(c);
  var whole = String(Math.floor(c / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return sign + '$' + whole + (c % 100 ? '.' + pad(c % 100) : '');
}
function normalizeTime(text) {
  var m = String(text || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '')
    .match(/^(\d{1,2})(?:[:.h](\d{2}))?(a\.?m\.?|p\.?m\.?)?$/);
  if (!m) return null;
  var h = Number(m[1]);
  var min = m[2] ? Number(m[2]) : 0;
  if (m[3]) {
    if (h < 1 || h > 12) return null;
    if (m[3].charAt(0) === 'p' && h !== 12) h += 12;
    if (m[3].charAt(0) === 'a' && h === 12) h = 0;
  }
  if (h > 23 || min > 59) return null;
  return pad(h) + ':' + pad(min);
}
function clock(hhmm) {
  var parts = String(hhmm || '').split(':');
  var h = Number(parts[0]);
  if (!isFinite(h) || parts.length !== 2) return String(hhmm || '');
  return ((h % 12) || 12) + (parts[1] === '00' ? '' : ':' + parts[1]) + (h < 12 ? ' am' : ' pm');
}
function normalizeDietary(text) {
  var t = String(text || '').trim().toLowerCase().replace(/\s+/g, ' ').replace(/[.!]+$/, '');
  if (!t) return '';
  if (/^(none|no|nothing|n\/?a|no restrictions?|no needs|no dietary needs|nothing special|eats anything|anything)$/.test(t)) return 'none';
  var aliases = {
    veg: 'vegetarian',
    veggie: 'vegetarian',
    gf: 'gluten-free',
    'gluten free': 'gluten-free',
    'no gluten': 'gluten-free',
    'dairy free': 'dairy-free',
    'no dairy': 'dairy-free',
    nuts: 'nut allergy',
    'no nuts': 'nut allergy',
    'nut free': 'nut allergy',
  };
  return aliases[t] || t;
}
function people(guest) {
  var n = Number(guest && guest.fields && guest.fields.partySize);
  return n >= 1 ? Math.round(n) : 1;
}
function paidFor(vendorId, entries) {
  return entries
    .filter(function (e) {
      return e.kind === 'out' && e.data && e.data.vendorId === vendorId;
    })
    .reduce(function (sum, e) {
      return sum + (Number(e.amountCents) || 0);
    }, 0);
}
function blankEvent() {
  return { version: 1, occasion: '', date: '', time: '', venue: '', host: '', rsvp: '', headcount: 0, budgetCents: 0, program: [] };
}
function guestTag(g, extra) {
  var f = g.fields || {};
  return f.name + ' (' + g.id + (f.company ? ', ' + f.company : '') + (extra ? ', ' + extra : '') + (people(g) > 1 ? ', party of ' + people(g) : '') + ')';
}
function venueCost(venue, guests) {
  var f = venue.fields || {};
  var fee = Number(f.feeCents) || 0;
  var perHead = Number(f.cateringPerHeadCents) || 0;
  var total = fee + perHead * guests;
  return { fee: fee, perHead: perHead, total: total, each: guests > 0 ? Math.round(total / guests) : 0 };
}
function compareVenues(venues, guests) {
  var live = venues.filter(function (v) {
    return v.status !== 'declined';
  });
  if (!live.length) return { fits: 0, summary: 'No venues on the shortlist yet.' };
  var rows = live.map(function (v) {
    var f = v.fields || {};
    var cap = Number(f.capacity) || 0;
    var cost = venueCost(v, guests);
    return { v: v, cap: cap, fits: cap >= guests, cost: cost };
  });
  rows.sort(function (a, b) {
    return (b.fits ? 1 : 0) - (a.fits ? 1 : 0) || a.cost.each - b.cost.each;
  });
  var lines = rows.map(function (r) {
    var f = r.v.fields || {};
    return (
      f.name + ' (' + r.v.id + ', ' + r.v.status + '): ' +
      (r.cap ? 'holds ' + r.cap + (r.fits ? ', fits ' + guests : ', ' + (guests - r.cap) + ' short for ' + guests) : 'capacity unknown') +
      '; hire ' + money(r.cost.fee) +
      (r.cost.perHead
        ? ' plus in-house catering at ' + money(r.cost.perHead) + ' a guest = ' + money(r.cost.total) + ' for ' + guests + ' (' + money(r.cost.each) + ' a guest)'
        : ', bring your own caterer') +
      '; sound and screens ' + (f.av === 'included' ? 'included' : 'extra') +
      (f.location ? '; ' + f.location : '') +
      (f.notes ? '; ' + f.notes : '')
    );
  });
  var fit = rows.filter(function (r) { return r.fits; });
  var small = rows.filter(function (r) { return r.cap && !r.fits; });
  return {
    fits: fit.length,
    summary:
      'Venues for ' + guests + ' guests, those that fit first: ' + lines.join(' | ') + '. ' +
      (fit.length ? 'Fits ' + guests + ': ' + fit.map(function (r) { return r.v.fields.name; }).join(', ') + '.' : 'None of them holds ' + guests + '.') +
      (small.length ? ' Too small: ' + small.map(function (r) { return r.v.fields.name; }).join(', ') + '.' : ''),
  };
}
function deskPicture(event, venues, vendors, guests, entries, nowMs) {
  var ev = event || blankEvent();
  var parts = [];
  var days = isDay(ev.date) ? daysLeft(ev.date, nowMs) : null;
  parts.push(
    (ev.occasion || 'The event') +
      (days === null ? (ev.date ? ', date to confirm (' + ev.date + ')' : ', date not set') : ' on ' + ev.date + (days > 0 ? ' (' + days + (days === 1 ? ' day' : ' days') + ' to go)' : days === 0 ? ' (today)' : ' (' + -days + ' days ago)')) +
      (ev.time ? ', ' + ev.time : '') +
      (ev.venue ? ', at ' + ev.venue : ', venue not booked yet') +
      (ev.host ? ', hosted by ' + ev.host : '') +
      '.',
  );
  var yes = guests.filter(function (g) { return g.status === 'yes'; });
  var no = guests.filter(function (g) { return g.status === 'no'; });
  var waiting = guests.filter(function (g) { return g.status === 'invited'; });
  var attending = yes.reduce(function (sum, g) { return sum + people(g); }, 0);
  parts.push(
    'RSVPs: ' + yes.length + ' yes (' + attending + (attending === 1 ? ' person' : ' people') + ' with the guests they bring), ' + no.length + ' no, ' + waiting.length + ' not replied yet' +
      (ev.headcount ? '; planning for ' + ev.headcount : '') + '.',
  );
  // One list a dietary question selects: attending guests first, then those who have not replied.
  var noAnswer = yes.filter(function (g) { return !g.fields.dietary; });
  var pending = noAnswer.map(function (g) { return guestTag(g, 'attending'); }).concat(
    waiting.filter(function (g) { return !g.fields.dietary; }).map(function (g) { return guestTag(g, 'not replied'); }),
  );
  parts.push(
    !guests.length ? 'No guests on the list yet.' : pending.length ? 'No dietary answer yet, attending first: ' + pending.join(' | ') + '.' : 'Every guest has a dietary answer.',
  );
  var tally = {};
  yes.forEach(function (g) {
    var d = g.fields.dietary;
    if (d && d !== 'none') tally[d] = (tally[d] || 0) + 1;
  });
  var needs = Object.keys(tally).sort().map(function (d) { return d + ' ' + tally[d]; });
  parts.push(needs.length ? 'Dietary needs among those attending: ' + needs.join(', ') + '.' : 'No dietary needs among those attending so far.');
  if (waiting.length) parts.push('Not replied yet: ' + waiting.map(function (g) { return guestTag(g, ''); }).join(', ') + '.');

  var live = vendors.filter(function (v) { return v.status !== 'dropped'; });
  var due = [];
  live.forEach(function (v) {
    var f = v.fields || {};
    var paid = paidFor(v.id, entries);
    var deposit = Number(f.depositCents) || 0;
    if (v.status !== 'quoted' && deposit > paid) {
      due.push({ at: f.depositDueAt || '9999-12-31', text: f.name + ' (' + v.id + ') deposit ' + money(deposit - paid) + (isDay(f.depositDueAt) ? ', due ' + f.depositDueAt + ' (' + when(daysLeft(f.depositDueAt, nowMs)) + ')' : ', no due date') });
    }
  });
  due.sort(function (a, b) { return a.at.localeCompare(b.at); });
  parts.push(due.length ? 'Deposits still to pay, soonest first: ' + due.map(function (d) { return d.text; }).join(' | ') + '.' : 'No deposits outstanding.');

  var signed = live.filter(function (v) { return v.status === 'booked' || v.status === 'paid'; });
  var contracted = signed.reduce(function (sum, v) { return sum + (Number(v.fields.contractCents) || 0); }, 0);
  var paidTotal = entries.filter(function (e) { return e.kind === 'out'; }).reduce(function (sum, e) { return sum + (Number(e.amountCents) || 0); }, 0);
  var budget = Number(ev.budgetCents) || 0;
  var left = budget - contracted;
  parts.push(
    (budget ? 'Budget ' + money(budget) + ': ' : 'No budget set: ') +
      money(contracted) + ' signed with booked vendors, ' + money(paidTotal) + ' paid, ' + money(contracted - paidTotal) + ' still owed on signed contracts' +
      (budget ? ', ' + (left >= 0 ? money(left) + ' left to commit' : money(-left) + ' over budget') : '') + '.',
  );
  parts.push(
    live.length
      ? 'Vendors: ' + live.map(function (v) {
          var f = v.fields || {};
          return f.name + ' (' + v.id + ', ' + (f.category || 'other') + ', ' + v.status + (f.contractCents ? ', ' + money(f.contractCents) : '') + ', paid ' + money(paidFor(v.id, entries)) + (f.arrival ? ', arrives ' + clock(f.arrival) : '') + ')';
        }).join(' | ') + '.'
      : 'No vendors yet.',
  );
  parts.push(
    venues.length
      ? 'Venues: ' + venues.map(function (v) { return v.fields.name + ' (' + v.id + ', ' + v.status + (v.fields.capacity ? ', holds ' + v.fields.capacity : '') + ')'; }).join(', ') + '.'
      : 'No venues on the shortlist yet.',
  );
  var program = (ev.program || []).slice().sort(function (a, b) { return String(a.time).localeCompare(String(b.time)); });
  parts.push(
    program.length
      ? 'Run of show: ' + program.map(function (p) { return clock(p.time) + ' ' + p.item + (p.owner ? ' (' + p.owner + ')' : ''); }).join(' | ') + '.'
      : 'The run of show is empty.',
  );
  return { attending: attending, noDietaryAnswer: noAnswer.map(function (g) { return String(g.fields.name); }), budgetLeftCents: left, summary: parts.join(' ') };
}
// ── event-desk-rules-end ──

const venues = rosterStore(gezel.fs, 'venues.json', {
  stages: ['shortlisted', 'visited', 'held', 'booked', 'declined'],
  idPrefix: 've',
});
const vendors = rosterStore(gezel.fs, 'vendors.json', {
  stages: ['quoted', 'booked', 'paid', 'dropped'],
  idPrefix: 'vn',
});
const guests = rosterStore(gezel.fs, 'guests.json', { stages: ['invited', 'yes', 'no'], idPrefix: 'gu' });
const budget = ledgerStore(gezel.fs, 'budget.json');

interface ProgramItem {
  id: string;
  time: string;
  item: string;
  owner?: string;
  note?: string;
}
interface EventDoc {
  version: 1;
  occasion: string;
  date: string;
  time: string;
  venue: string;
  venueId?: string;
  host: string;
  rsvp: string;
  headcount: number;
  budgetCents: number;
  program: ProgramItem[];
}

async function readEvent(): Promise<EventDoc> {
  let raw: string;
  try {
    raw = await gezel.fs.read('event.json');
  } catch {
    return blankEvent() as EventDoc;
  }
  let doc: Partial<EventDoc>;
  try {
    doc = JSON.parse(raw);
  } catch {
    throw new Error('event.json is not valid JSON. Fix or remove it; it will not be overwritten automatically.');
  }
  if (doc.version !== 1) throw new Error('event.json has unsupported version ' + String(doc.version) + ' (expected 1).');
  return { ...(blankEvent() as EventDoc), ...doc, program: Array.isArray(doc.program) ? doc.program : [] };
}

// A record by id or by (partial) name; a clear error names the matches.
function pick(all: RosterRecord[], what: string, example: string): RosterRecord | null {
  if (input.id) {
    const byId = all.find((r) => r.id === input.id);
    if (byId) return byId;
    throw new Error('No ' + what + " with id '" + input.id + "'. Known: " + (all.map((r) => r.id + ' ' + String(r.fields.name)).join(', ') || 'none') + '.');
  }
  if (!input.name) throw new Error("Pass 'id' (e.g. '" + example + "') or the " + what + "'s 'name'.");
  const exact = all.filter((r) => nameMatch(r.fields.name, input.name) === 'exact');
  if (exact.length === 1) return exact[0]!;
  const partial = all.filter((r) => nameMatch(r.fields.name, input.name) === 'partial');
  if (partial.length === 1) return partial[0]!;
  if (partial.length > 1) {
    throw new Error('More than one ' + what + " matches '" + input.name + "': " + partial.map((r) => r.id + ' ' + String(r.fields.name)).join(', ') + '. Pass id.');
  }
  return null;
}
function mustPick(all: RosterRecord[], what: string, example: string): RosterRecord {
  const found = pick(all, what, example);
  if (found) return found;
  throw new Error('No ' + what + " named '" + input.name + "'. Known: " + (all.map((r) => r.id + ' ' + String(r.fields.name)).join(', ') || 'none') + '.');
}
function dollars(value: unknown, label: string, allowNegative = false): number | null {
  if (value === undefined || value === null || value === '') return null;
  const cents = toCents(value);
  if (cents === null || (!allowNegative && cents < 0)) throw new Error(label + ' must be an amount in dollars, e.g. 1800.');
  return cents;
}

const event = await readEvent();
let eventChanged = false;
let note = '';
let reply = '';

if (input.action === 'set_event') {
  const given = ['occasion', 'date', 'time', 'host', 'rsvp', 'headcount', 'budget', 'budgetChange'].filter(
    (k) => (input as Record<string, unknown>)[k] !== undefined && (input as Record<string, unknown>)[k] !== '',
  );
  if (!given.length) throw new Error('set_event needs at least one of occasion, date, time, host, rsvp, headcount, budget or budgetChange.');
  if (input.occasion) event.occasion = input.occasion.trim();
  if (input.date) {
    const day = normalizeDate(input.date);
    if (!day) throw new Error("date must be a date, e.g. '2026-12-10'.");
    event.date = day;
  }
  if (input.time) event.time = input.time.trim();
  if (input.host) event.host = input.host.trim();
  if (input.rsvp) event.rsvp = input.rsvp.trim();
  if (typeof input.headcount === 'number') {
    if (!(input.headcount >= 1)) throw new Error('headcount must be at least 1.');
    event.headcount = Math.round(input.headcount);
  }
  const whole = dollars(input.budget, 'budget');
  if (whole !== null) event.budgetCents = whole;
  const change = dollars(input.budgetChange, 'budgetChange', true);
  if (change !== null) event.budgetCents = Math.max(0, (Number(event.budgetCents) || 0) + change);
  eventChanged = true;
  note = 'Saved the event details' + (whole !== null || change !== null ? '; the budget is now ' + money(event.budgetCents) : '') + '.';
} else if (input.action === 'add_venue') {
  if (!input.name) throw new Error("add_venue needs 'name'.");
  if (input.status && !VENUE_STAGES.includes(input.status)) throw new Error("A venue's status is shortlisted, visited, held, or declined.");
  const fee = dollars(input.fee, 'fee');
  const catering = dollars(input.cateringPerHead, 'cateringPerHead');
  const fields: Record<string, unknown> = {
    ...(typeof input.capacity === 'number' && input.capacity > 0 ? { capacity: Math.round(input.capacity) } : {}),
    ...(fee !== null ? { feeCents: fee } : {}),
    ...(catering !== null ? { cateringPerHeadCents: catering } : {}),
    ...(input.av === 'included' || input.av === 'extra' ? { av: input.av } : {}),
    ...(input.location ? { location: input.location.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  const existing = (await venues.list()).find((r) => key(r.fields.name) === key(input.name));
  let record: RosterRecord;
  if (existing) {
    record = await venues.update(existing.id, { fields });
    note = 'Updated ' + String(existing.fields.name) + '.';
  } else {
    record = await venues.add({ status: 'shortlisted', fields: { name: input.name.trim(), av: 'extra', ...fields } });
    note = 'Added ' + input.name.trim() + ' (' + record.id + ') to the shortlist.';
  }
  if (input.status === 'booked') await bookVenue(record);
  else if (input.status && input.status !== record.status) await venues.transition(record.id, input.status, input.note ? { note: input.note } : {});
} else if (input.action === 'book_venue') {
  await bookVenue(mustPick(await venues.list(), 'venue', 've-2'));
} else if (input.action === 'add_vendor') {
  if (!input.name) throw new Error("add_vendor needs 'name'.");
  if (input.status && !['quoted', 'booked', 'dropped'].includes(input.status)) throw new Error("A vendor's status is quoted, booked, or dropped.");
  const existing = (await vendors.list()).find((r) => key(r.fields.name) === key(input.name));
  const contract = dollars(input.contract, 'contract');
  const change = dollars(input.contractChange, 'contractChange', true);
  const deposit = dollars(input.deposit, 'deposit');
  const dueAt = input.depositDueAt ? normalizeDate(input.depositDueAt) : null;
  if (input.depositDueAt && !dueAt) throw new Error("depositDueAt must be a date, e.g. '2026-11-12'.");
  const arrival = input.arrival ? normalizeTime(input.arrival) : null;
  if (input.arrival && !arrival) throw new Error("arrival must be a time, e.g. '2 pm' or '14:00'.");
  let total = contract;
  if (change !== null) total = Math.max(0, (total ?? (Number(existing?.fields.contractCents) || 0)) + change);
  const fields: Record<string, unknown> = {
    ...(input.category && VENDOR_KINDS.includes(input.category) ? { category: input.category } : {}),
    ...(total !== null ? { contractCents: total } : {}),
    ...(deposit !== null ? { depositCents: deposit } : {}),
    ...(dueAt ? { depositDueAt: dueAt } : {}),
    ...(input.contact ? { contact: input.contact.trim() } : {}),
    ...(arrival ? { arrival } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  if (existing) {
    await vendors.update(existing.id, { fields });
    if (input.status && input.status !== existing.status) await vendors.transition(existing.id, input.status, input.note ? { note: input.note } : {});
    note = 'Updated ' + String(existing.fields.name) + (total !== null ? '; total now ' + money(total) : '') + '.';
  } else {
    const record = await vendors.add({
      status: input.status ?? 'quoted',
      fields: { name: input.name.trim(), category: 'other', contractCents: 0, depositCents: 0, ...fields },
    });
    note = 'Added ' + input.name.trim() + ' (' + record.id + ', ' + record.status + ').';
  }
} else if (input.action === 'pay') {
  const cents = dollars(input.amount, 'amount');
  if (!cents || cents <= 0) throw new Error("pay needs a positive 'amount' in dollars.");
  const vendor = mustPick(await vendors.list(), 'vendor', 'vn-2');
  const entries = await budget.list();
  const before = paidFor(vendor.id, entries);
  const deposit = Number(vendor.fields.depositCents) || 0;
  const kind = ['deposit', 'balance', 'other'].includes(String(input.kind)) ? String(input.kind) : before < deposit ? 'deposit' : 'balance';
  const today = localDay(Date.now());
  const repeat = entries.find(
    (e) => e.data && e.data.vendorId === vendor.id && e.amountCents === cents && e.data.payment === kind && localDay(Date.parse(e.at)) === today,
  );
  const name = String(vendor.fields.name);
  if (repeat) {
    note = 'Already recorded: ' + money(cents) + ' ' + kind + ' to ' + name + ' today.';
  } else {
    await budget.add({
      amountCents: cents,
      kind: 'out',
      category: String(vendor.fields.category ?? 'other'),
      note: input.note ? input.note.trim() : kind.charAt(0).toUpperCase() + kind.slice(1) + ' to ' + name,
      data: { vendorId: vendor.id, vendor: name, payment: kind },
    });
    const paid = before + cents;
    const contract = Number(vendor.fields.contractCents) || 0;
    if (contract > 0 && paid >= contract && vendor.status !== 'paid') await vendors.transition(vendor.id, 'paid', { note: 'Paid in full' });
    else if (vendor.status === 'quoted' || vendor.status === 'dropped') await vendors.transition(vendor.id, 'booked', { note: 'Booked with a payment' });
    note =
      'Paid ' + money(cents) + ' ' + kind + ' to ' + name + '; ' +
      (contract ? money(paid) + ' of ' + money(contract) + ' paid' + (paid >= contract ? ', paid in full' : ', ' + money(contract - paid) + ' to go') : money(paid) + ' paid so far') + '.';
  }
} else if (input.action === 'add_guest' || input.action === 'rsvp') {
  if (input.response && !GUEST_STAGES.includes(input.response)) throw new Error("response is invited, yes, or no.");
  const all = await guests.list();
  let guest: RosterRecord | null;
  if (input.action === 'add_guest') {
    if (!input.name) throw new Error("add_guest needs 'name'.");
    guest = all.find((r) => key(r.fields.name) === key(input.name)) ?? null;
  } else {
    if (!input.response && !input.dietary && typeof input.joining !== 'number' && typeof input.partySize !== 'number') {
      throw new Error("rsvp needs 'response' (yes or no), 'dietary', or 'joining'.");
    }
    guest = pick(all, 'guest', 'gu-4');
  }
  const dietary = input.dietary ? normalizeDietary(input.dietary) : '';
  const party =
    typeof input.partySize === 'number' && input.partySize >= 1
      ? Math.round(input.partySize)
      : typeof input.joining === 'number' && input.joining > 0
        ? (guest ? people(guest) : 1) + Math.round(input.joining)
        : null;
  const fields: Record<string, unknown> = {
    ...(input.company ? { company: input.company.trim() } : {}),
    ...(dietary ? { dietary } : {}),
    ...(party !== null ? { partySize: party } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  if (guest) {
    await guests.update(guest.id, { fields });
    if (input.response && input.response !== guest.status) await guests.transition(guest.id, input.response, input.note ? { note: input.note } : {});
  } else {
    if (!input.name) throw new Error("Pass the guest's 'name'.");
    guest = await guests.add({ status: input.response ?? 'invited', fields: { name: input.name.trim(), partySize: 1, ...fields } });
  }
  const now = (await guests.get(guest.id))!;
  const label = String(now.fields.name);
  note =
    (all.some((r) => r.id === now.id) ? '' : 'Added ' + label + ' (' + now.id + ') to the list. ') +
    label + (now.status === 'yes' ? ' is coming' : now.status === 'no' ? " can't come" : ' is invited') +
    (people(now) > 1 ? ' with ' + (people(now) - 1) + ' more (party of ' + people(now) + ')' : '') +
    (now.fields.dietary ? '; dietary: ' + String(now.fields.dietary) : now.status === 'yes' ? '; no dietary answer yet' : '') + '.';
} else if (input.action === 'program') {
  if (!input.item) throw new Error("program needs 'item'.");
  const wanted = key(input.item);
  const list = event.program;
  let hits = list.filter((p) => key(p.item) === wanted);
  if (!hits.length) hits = list.filter((p) => key(p.item).includes(wanted));
  if (input.remove) {
    if (hits.length !== 1) throw new Error(hits.length ? 'More than one item matches: ' + hits.map((p) => clock(p.time) + ' ' + p.item).join(', ') + '.' : "No run-of-show item matches '" + input.item + "'.");
    event.program = list.filter((p) => p !== hits[0]);
    note = 'Took ' + hits[0]!.item + ' off the run of show.';
  } else {
    const time = input.time ? normalizeTime(input.time) : null;
    if (input.time && !time) throw new Error("time must be a clock time, e.g. '4:30 pm' or '16:30'.");
    const same = list.find((p) => key(p.item) === wanted);
    if (same) {
      if (time) same.time = time;
      if (input.owner) same.owner = input.owner.trim();
      if (input.note) same.note = input.note.trim();
      note = 'Run of show: ' + clock(same.time) + ' ' + same.item + (same.owner ? ' (' + same.owner + ')' : '') + '.';
    } else {
      if (!time) throw new Error("A new run-of-show item needs 'time', e.g. '4:30 pm'.");
      const next = list.reduce((max, p) => Math.max(max, Number(String(p.id).split('-')[1]) || 0), 0) + 1;
      list.push({ id: 'rs-' + next, time, item: input.item.trim(), ...(input.owner ? { owner: input.owner.trim() } : {}), ...(input.note ? { note: input.note.trim() } : {}) });
      note = 'Added to the run of show: ' + clock(time) + ' ' + input.item.trim() + (input.owner ? ' (' + input.owner.trim() + ')' : '') + '.';
    }
    event.program.sort((a, b) => String(a.time).localeCompare(String(b.time)));
  }
  eventChanged = true;
} else if (input.action === 'compare') {
  const yes = (await guests.list()).filter((g) => g.status === 'yes').reduce((sum, g) => sum + people(g), 0);
  const count = typeof input.guests === 'number' && input.guests > 0 ? Math.round(input.guests) : Number(event.headcount) || yes;
  if (!count) throw new Error("Pass 'guests', the headcount to compare for.");
  reply = compareVenues(await venues.list(), count).summary;
} else if (input.action === 'guests') {
  const order = { yes: 0, invited: 1, no: 2 } as Record<string, number>;
  reply =
    (await guests.list())
      .slice()
      .sort((a, b) => (order[a.status] ?? 3) - (order[b.status] ?? 3) || String(a.fields.name).localeCompare(String(b.fields.name)))
      .map((g) => '[' + g.status + '] ' + guestTag(g, '') + ': ' + (g.fields.dietary ? String(g.fields.dietary) : 'no dietary answer'))
      .join('\n') || 'The guest list is empty.';
} else if (input.action !== 'status') {
  throw new Error("Unknown action '" + input.action + "'. Use status, compare, add_venue, book_venue, add_vendor, pay, add_guest, rsvp, set_event, program, or guests.");
}

// Booking a venue makes it the event's venue and puts its hire fee in the contracts.
async function bookVenue(record: RosterRecord): Promise<void> {
  const released: string[] = [];
  const entries = await budget.list();
  for (const other of await venues.list()) {
    if (other.id === record.id || other.status !== 'booked') continue;
    await venues.transition(other.id, 'declined', { note: 'Released when ' + String(record.fields.name) + ' was booked' });
    const line = (await vendors.list()).find((v) => v.fields.venueId === other.id);
    if (line && line.status !== 'dropped' && paidFor(line.id, entries) === 0) await vendors.transition(line.id, 'dropped', { note: 'Venue released' });
    released.push(String(other.fields.name));
  }
  if (record.status !== 'booked') await venues.transition(record.id, 'booked', input.note ? { note: input.note } : {});
  const fee = Number(record.fields.feeCents) || 0;
  const all = await vendors.list();
  const line = all.find((v) => v.fields.venueId === record.id) ?? all.find((v) => key(v.fields.name) === key(record.fields.name));
  if (line) {
    await vendors.update(line.id, { fields: { category: 'venue', venueId: record.id, contractCents: fee } });
    if (line.status === 'quoted' || line.status === 'dropped') await vendors.transition(line.id, 'booked', { note: 'Venue booked' });
  } else {
    await vendors.add({
      status: 'booked',
      fields: { name: String(record.fields.name), category: 'venue', venueId: record.id, contractCents: fee, depositCents: 0, notes: 'Venue hire' },
    });
  }
  event.venue = String(record.fields.name);
  event.venueId = record.id;
  eventChanged = true;
  const perHead = Number(record.fields.cateringPerHeadCents) || 0;
  note =
    'Booked ' + String(record.fields.name) + ' (' + record.id + '); its ' + money(fee) + ' hire fee is now with the signed contracts' +
    (perHead ? ', and its in-house catering at ' + money(perHead) + ' a guest goes in as a vendor once the count is final' : '') +
    (released.length ? '. Released ' + released.join(', ') : '') + '.';
}

if (eventChanged) await gezel.fs.write('event.json', JSON.stringify(event, null, 2) + '\n');

const view = deskPicture(event, await venues.list(), await vendors.list(), await guests.list(), await budget.list(), Date.now());

gezel.output({
  attending: view.attending,
  noDietaryAnswer: view.noDietaryAnswer,
  budgetLeft: view.budgetLeftCents / 100,
  summary: reply || (note ? note + ' ' : '') + view.summary,
});

